#!/usr/bin/env bash
# Writes each model's table of invariants into docs/walkthroughs/README.md:
# what each means, the code that enforces it and the tests that check it,
# generated by `gotogether invariants` from the model and the code's
# //quint:enforces and //quint:checks annotations. With -check it writes
# nothing and fails when a table is stale (CI). Either way it fails when an
# invariant has no enforcing code or no test.
#
# Needs quint, and the gotogether CLI at the version go.mod requires:
#   go install "github.com/chucklehead-dev/gotogether/cmd/gotogether@$(go list -m -f '{{.Version}}' github.com/chucklehead-dev/gotogether)"
set -euo pipefail
cd "$(dirname "$0")/.."
mode=write
case ${1:-} in
  "") ;;
  -check) mode=check ;;
  *) echo "usage: model/invariants.sh [-check]" >&2; exit 2 ;;
esac
GOTOGETHER=${GOTOGETHER:-gotogether}
doc=docs/walkthroughs/README.md

# Each model, then the packages its annotations are in. gotogether
# invariants refuses a directive that names another model's property, so a
# model's scan must not reach another's annotations (exposure and attempts
# both have a withinBound). An annotation outside its model's packages is
# not seen: add its package here.
models=(
  "publication ./gateway/snapshot ./control/..."
  "exposure ./gateway/limit"
  "attempts ./gateway/proxy ./gateway/route ./gateway/telemetry"
)

# gotogether writes one table per document, between its two marker lines,
# with links relative to the document's directory. So each model's table
# is generated in a scratch document beside $doc, between the lines
# gotogether expects, and spliced into $doc between the model's own markers.
begin="<!-- gotogether:invariants -->"
end="<!-- /gotogether:invariants -->"
# No .md suffix: gotogether would take a .md for a literate model.
tmp=$(mktemp "$(dirname "$doc")/.invariants-XXXXXX")
trap 'rm -f "$tmp" "$tmp.doc"' EXIT

fail=0
for entry in "${models[@]}"; do
  read -r m dirs <<<"$entry"
  b="<!-- gotogether:invariants $m -->" e="<!-- /gotogether:invariants $m -->"
  if ! grep -qxF "$b" "$doc" || ! grep -qxF "$e" "$doc"; then
    echo "FAIL $doc: no $b ... $e lines: add them where model $m's table goes" >&2
    fail=1
    continue
  fi
  # The model's table as $doc has it, between gotogether's markers.
  awk -v b="$b" -v e="$e" -v B="$begin" -v E="$end" '
    $0 == b { on = 1; print B; next }
    $0 == e { on = 0; print E; next }
    on { print }' "$doc" >"$tmp"
  # shellcheck disable=SC2086 # dirs is a list of patterns
  if [[ $mode == check ]]; then
    out=$("$GOTOGETHER" invariants -binding "model/$m.invariants.yaml" -check "$tmp" -require enforced,checked $dirs 2>&1) || fail=1
  else
    out=$("$GOTOGETHER" invariants -binding "model/$m.invariants.yaml" -write "$tmp" -require enforced,checked $dirs 2>&1) || fail=1
    # The table written, back between the model's markers in $doc.
    awk -v b="$b" -v e="$e" -v B="$begin" -v E="$end" -v f="$tmp" '
      BEGIN {
        while ((getline line < f) > 0) {
          if (line == B) { on = 1; continue }
          if (line == E) { on = 0; continue }
          if (on) table = table line "\n"
        }
      }
      $0 == b { print; printf "%s", table; skip = 1; next }
      $0 == e { skip = 0 }
      !skip { print }' "$doc" >"$tmp.doc"
    mv "$tmp.doc" "$doc"
  fi
  # gotogether names the scratch document, and its fix is for it: say $doc's.
  out=${out//"$tmp"/"$doc ($m)"}
  sed -E 's#: run gotogether invariants .*#: run model/invariants.sh#' <<<"$out"
done
if ((fail)) && [[ $mode == check ]]; then
  echo "run model/invariants.sh to write the tables again, and annotate any invariant it names (docs/contributing.md, Model invariants)" >&2
fi
exit $fail
